/// Every primitive datatype. There are 20.
pub const PRIMITIVE_TYPES: &[&str] = &[
    "base64Binary",
    "boolean",
    "canonical",
    "code",
    "date",
    "dateTime",
    "decimal",
    "id",
    "instant",
    "integer",
    "markdown",
    "oid",
    "positiveInt",
    "string",
    "time",
    "unsignedInt",
    "uri",
    "url",
    "uuid",
    "xhtml",
];

/// The regular expression a primitive's lexical value must match, as the
/// `structuredefinition-regex` extension on its `value` element declares it.
/// `xhtml` declares none, so it is absent rather than unconstrained-by-
/// accident.
const fn rx(name: &'static str, regex: &'static str) -> (&'static str, &'static str) {
    (name, regex)
}
pub const PRIMITIVE_VALUE_REGEX: &[(&str, &str)] = &[
    rx("base64Binary", "(\\s*([0-9a-zA-Z\\+/=]){4}\\s*)+"),
    rx("boolean", "true|false"),
    rx("canonical", "\\S*"),
    rx("code", "[^\\s]+(\\s[^\\s]+)*"),
    rx(
        "date",
        "([0-9]([0-9]([0-9][1-9]|[1-9]0)|[1-9]00)|[1-9]000)(-(0[1-9]|1[0-2])(-(0[1-9]|[1-2][0-9]|3[0-1]))?)?",
    ),
    rx(
        "dateTime",
        "([0-9]([0-9]([0-9][1-9]|[1-9]0)|[1-9]00)|[1-9]000)(-(0[1-9]|1[0-2])(-(0[1-9]|[1-2][0-9]|3[0-1])(T([01][0-9]|2[0-3]):[0-5][0-9]:([0-5][0-9]|60)(\\.[0-9]+)?(Z|(\\+|-)((0[0-9]|1[0-3]):[0-5][0-9]|14:00)))?)?)?",
    ),
    rx("decimal", "-?(0|[1-9][0-9]*)(\\.[0-9]+)?([eE][+-]?[0-9]+)?"),
    rx("id", "[A-Za-z0-9\\-\\.]{1,64}"),
    rx(
        "instant",
        "([0-9]([0-9]([0-9][1-9]|[1-9]0)|[1-9]00)|[1-9]000)-(0[1-9]|1[0-2])-(0[1-9]|[1-2][0-9]|3[0-1])T([01][0-9]|2[0-3]):[0-5][0-9]:([0-5][0-9]|60)(\\.[0-9]+)?(Z|(\\+|-)((0[0-9]|1[0-3]):[0-5][0-9]|14:00))",
    ),
    rx("integer", "-?([0]|([1-9][0-9]*))"),
    rx("markdown", "[ \\r\\n\\t\\S]+"),
    rx("oid", "urn:oid:[0-2](\\.(0|[1-9][0-9]*))+"),
    rx("positiveInt", "[1-9][0-9]*"),
    rx("string", "[ \\r\\n\\t\\S]+"),
    rx(
        "time",
        "([01][0-9]|2[0-3]):[0-5][0-9]:([0-5][0-9]|60)(\\.[0-9]+)?",
    ),
    rx("unsignedInt", "[0]|([1-9][0-9]*)"),
    rx("uri", "\\S*"),
    rx("url", "\\S*"),
    rx(
        "uuid",
        "urn:uuid:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}",
    ),
];
